Let $0\leq p,q\leq n$. We say that an $n$-dimensional compact complex manifold $X$ satisfies $\mathbb S^{p,q}$  (resp. $\mathbb B^{p,q}$) if for every $\partial \alpha \in A^{p,q}(X)$ with $\partial\bar\partial \alpha=0$,  the equation $$\bar\partial \beta=\partial \alpha$$
	admits a solution (resp. a $\partial$-exact solution).  Clearly,
	\begin{equation}\label{www}
		\partial\bar\partial\text{-lemma}\Longrightarrow \mathbb B^{p,q}\Longrightarrow \mathbb S^{p,q}, \quad\text{for every }p,q.
	\end{equation}

\label{cor 1}
		Let $X$ be as in Theorem  \ref{main thm}
		or Theorem  \ref{main thm2}.
		Then $\operatorname{Kur}(X,L)$ is smooth
		for every $L\in\operatorname{Pic}(X)$.

\label{simple}
		Let $X$ be a K\"ahler $K$-trivial Calabi--Yau surface, and let
		$E\rightarrow X$ be a simple holomorphic vector bundle. Then  $\mathrm{Kur}(X,E)$ is smooth.

Let $X$ be a complex torus of dimension $n\geq2$,
		and let $L\in\operatorname{Pic}^0(X)$. Set
		\begin{equation*}
			E:=L^{\oplus r},\quad r\geq2.
		\end{equation*}
		Then $\operatorname{Kur}(X,E)$ is singular.

\label{def-joint defor}
		A \textit{family of (joint) deformations} of the pair $(X,E)$ over a  small disc $\mathbb D^m \subset \mathbb{C}^m$ centred at the origin consists of the following data:
		\begin{enumerate}[{$\centerdot$}]
			\item a proper smooth morphism $\pi: \mathcal{X} \to\mathbb D^m$
			with an isomorphism $ \pi^{-1}(0)\simeq X$;
			\item a holomorphic vector bundle $\mathcal{E} \to \mathcal{X}$ such that $\mathcal{E}|_{\pi^{-1}(0)} \simeq E$.
		\end{enumerate}

\label{prop:MC-pair}
		Let $(X,E)$ be a holomorphic pair and let
		\[
		\{(A_t,\varphi_t)\}_{t\in\mathbb D^m}
		\subset A^{0,1}(X,\operatorname{End} E)\oplus A^{0,1}(X,T_X^{1,0})
		\]
		be a family depending holomorphically on $t$. Then $(A_t,\varphi_t)$ defines a holomorphic family of pairs $(X_t,E_t)$ if and only if it satisfies the following  Maurer--Cartan system, consisting  of two equations:
		\begin{equation}\label{MC-pair}
			\left\{
			\begin{aligned}
				\bar{\partial}\varphi_t 
				&= \dfrac{1}{2}\,[\varphi_t,\varphi_t], \\[6pt]
				\bar{\partial}_{\operatorname{End} E} A_t 
				&=\varphi_t \,\lrcorner\, R_E 
				+ \varphi_t \,\lrcorner\, D^{1,0}_{\operatorname{End} E} A_t
				- \dfrac{1}{2}\,[A_t,A_t].
			\end{aligned}
			\right.
		\end{equation}

The main differences between Proposition \ref{prop-1} and \cite[Proposition 4.10]{LRW19}, as well as \cite[Proposition I.3]{Zha26} (both with $D=\varnothing$), are two-fold:
			\begin{enumerate}[(i)]
				\item An additional obstruction equation (the third equation in \textcolor{Red2}{\hyperref[log 0.2]{(\ref*{log 0.2})}}) needs to be solved simultaneously;
				\item The solutions $\varphi(t)$, $a(t)$ and $\Omega(t)$ are only required to be formal. 
				\begin{enumerate}[label=(\alph*)]
					\item In the arguments of \cite{LRW19,Zha26}, the smoothness of the corresponding  $\Omega(t)$  was used to ensure that $\Omega(t)$ has no zeros for small $t$ (since $\Omega(0)$ is nowhere vanishing).  However, formal solutions suffice as shown above.
					\item   As for $\varphi(t)$ and $a(t)$, formal solutions are also enough: once they are obtained, we can then choose particularly nice solutions whose smoothness is very standard (see Proposition \ref{prop:formal-vs-canonical}). 
				\end{enumerate}
				This omits the regularity arguments  as in \cite[proof of Theorem 4.12, pp. 36-39]{LRW19} and \cite[Appendix I, Step (III)]{Zha26}.
			\end{enumerate}

\label{Fujiki}
			Let $X$ be a Fujiki manifold, and let $(F,h_F)$ be a Hermitian flat holomorphic
			vector bundle on $X$. Write its Chern connection as
			$
			\nabla_F=D_F^{1,0}+\bar\partial_F.
			$
			Then $(X,F)$ satisfies the
			$D_F^{1,0}\bar\partial_F$-lemma. More precisely, for every
			$\nabla_F$-closed $F$-valued $(p,q)$-form $\alpha$ on $X$, the
			following conditions are equivalent:
			\begin{equation*}
				\nabla_F\text{-exactness}
				\Longleftrightarrow
				D_F^{1,0}\text{-exactness}
				\Longleftrightarrow
				\bar\partial_F\text{-exactness}
				\Longleftrightarrow
				D_F^{1,0}\bar\partial_F\text{-exactness}.
			\end{equation*}

\label{Fujino}
			Let $(X,D)$ be as in Theorem \ref{dbar-Fujiki},   and let $L$ be a holomorphic line bundle over $X$ such that  \begin{equation*}\label{satis}
				L-K_X=\sum_{i=1}^{s}q_iD_i\quad
				\text{in }
				\operatorname{Pic}_{\mathbb Q}(X),
				\quad
				q_i\in(0,1]\cap\mathbb Q.
			\end{equation*}
			Then the restriction map
			\begin{equation*}\label{VVV}
				H^q(X,L)\stackrel{{j}}{\longrightarrow} H^q(X^\circ,L|_{X^\circ})
			\end{equation*}
			is  injective, for all $q$.

\label{prop:weak-ddbar-threefold}
		There exists a compact complex threefold $X$ such that:
		\begin{enumerate}[{(1)}]
			\item $K_X\simeq\mathcal O_X$;
			\item \label{2222} $X$ satisfies
			$\mathbb S^{3,1}$, $\mathbb S^{3,2}$ and
			$\mathbb B^{2,2}$;
			\item \(
			E_1^{\bullet,\bullet}(X)
			\not\simeq
			E_\infty^{\bullet,\bullet}(X),
			\)
			then in particular, \(X\) does not satisfy the full
			\(\partial\bar\partial\)-lemma;
			\item  \label{4444} for any holomorphic vector bundle $E\rightarrow  X$  with $H^2(X,\operatorname{End}^{0}E)=0$, one has  $H^2(X, A(E))=0$.
		\end{enumerate}

\label{prop:nonzero-obstruction-example}
		There exist a compact complex sixfold $X$ and a simple
		holomorphic vector bundle $E$ of rank $2$ over $X$ such that:
		\begin{enumerate}[{(1)}]
			\item $K_X\simeq\mathcal O_X$;

			\item $X$ satisfies $\mathbb S^{6,1}$,
			$\mathbb S^{6,2}$ and $\mathbb B^{5,2}$;

			\item the Fr\"olicher spectral sequence of $X$ does not
			degenerate at $E_1$; in particular, $X$ does not satisfy
			the full $\partial\bar\partial$-lemma;

			\item the bundle $E$ satisfies
			\begin{equation*}
				H^2(X,\operatorname{End}^{0}E)=0,
				\quad
				H^2(X,\operatorname{End}E)\simeq\mathbb C,
				\quad
				H^2(X,A(E))\simeq\mathbb C^2.
			\end{equation*}
		\end{enumerate}
		Moreover, the forgetful morphism
		$\operatorname{Def}(X,E)\longrightarrow\operatorname{Def}(X)$
		is not smooth.
